  1→import {
  2→  Controller,
  3→  Post,
  4→  Get,
  5→  Delete,
  6→  Patch,
  7→  Body,
  8→  Param,
  9→  Query,
 10→  UseGuards,
 11→  Request,
 12→  ParseUUIDPipe,
 13→  HttpCode,
 14→  HttpStatus,
 15→  NotFoundException,
 16→  BadRequestException,
 17→} from '@nestjs/common';
 18→import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth, ApiQuery } from '@nestjs/swagger';
 19→import { ThrottlerGuard } from '@nestjs/throttler';
 20→import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
 21→import { SharesService } from './shares.service';
 22→import { CreateShareDto } from './dto/create-share.dto';
 23→import { AddShareKeysDto } from './dto/share-key.dto';
 24→import { UpdateEncryptedKeyDto } from './dto/update-encrypted-key.dto';
 25→import {
 26→  CreateShareResponseDto,
 27→  ReceivedShareResponseDto,
 28→  SentShareResponseDto,
 29→  PendingRotationResponseDto,
 30→  ShareKeyResponseDto,
 31→} from './dto/share-response.dto';
 32→
 33→interface RequestWithUser extends Request {
 34→  user: {
 35→    id: string;
 36→  };
 37→}
 38→
 39→@ApiTags('shares')
 40→@ApiBearerAuth()
 41→@UseGuards(JwtAuthGuard, ThrottlerGuard)
 42→@Controller('shares')
 43→export class SharesController {
 44→  constructor(private readonly sharesService: SharesService) {}
 45→
 46→  @Post()
 47→  @ApiOperation({
 48→    summary: 'Create a share',
 49→    description:
 50→      'Share an encrypted folder or file with another user. ' +
 51→      'The encryptedKey is the item key re-wrapped for the recipient via ECIES.',
 52→  })
 53→  @ApiResponse({ status: 201, description: 'Share created', type: CreateShareResponseDto })
 54→  @ApiResponse({ status: 401, description: 'Unauthorized' })
 55→  @ApiResponse({ status: 404, description: 'Recipient not found' })
 56→  @ApiResponse({ status: 409, description: 'Share already exists or self-share' })
 57→  async createShare(
 58→    @Request() req: RequestWithUser,
 59→    @Body() dto: CreateShareDto
 60→  ): Promise<{
 61→    shareId: string;
 62→    itemType: string;
 63→    ipnsName: string;
 64→    itemName: string;
 65→    encryptedKey: string;
 66→    createdAt: Date;
 67→  }> {
 68→    const share = await this.sharesService.createShare(req.user.id, dto);
 69→    return {
 70→      shareId: share.id,
 71→      itemType: share.itemType,
 72→      ipnsName: share.ipnsName,
 73→      itemName: share.itemName,
 74→      encryptedKey: share.encryptedKey.toString('hex'),
 75→      createdAt: share.createdAt,
 76→    };
 77→  }
 78→
 79→  @Get('received')
 80→  @ApiOperation({
 81→    summary: 'List received shares',
 82→    description: 'Get all active, non-hidden shares received by the authenticated user.',
 83→  })
 84→  @ApiResponse({
 85→    status: 200,
 86→    description: 'List of received shares',
 87→    type: [ReceivedShareResponseDto],
 88→  })
 89→  @ApiResponse({ status: 401, description: 'Unauthorized' })
 90→  async getReceivedShares(@Request() req: RequestWithUser): Promise<
 91→    Array<{
 92→      shareId: string;
 93→      sharerPublicKey: string;
 94→      itemType: string;
 95→      ipnsName: string;
 96→      itemName: string;
 97→      encryptedKey: string;
 98→      createdAt: Date;
 99→    }>
100→  > {
101→    const shares = await this.sharesService.getReceivedShares(req.user.id);
102→    return shares.map((s) => ({
103→      shareId: s.id,
104→      sharerPublicKey: s.sharer.publicKey,
105→      itemType: s.itemType,
106→      ipnsName: s.ipnsName,
107→      itemName: s.itemName,
108→      encryptedKey: s.encryptedKey.toString('hex'),
109→      createdAt: s.createdAt,
110→    }));
111→  }
112→
113→  @Get('sent')
114→  @ApiOperation({
115→    summary: 'List sent shares',
116→    description: 'Get all active shares created by the authenticated user.',
117→  })
118→  @ApiResponse({ status: 200, description: 'List of sent shares', type: [SentShareResponseDto] })
119→  @ApiResponse({ status: 401, description: 'Unauthorized' })
120→  async getSentShares(@Request() req: RequestWithUser): Promise<
121→    Array<{
122→      shareId: string;
123→      recipientPublicKey: string;
124→      itemType: string;
125→      ipnsName: string;
126→      itemName: string;
127→      createdAt: Date;
128→    }>
129→  > {
130→    const shares = await this.sharesService.getSentShares(req.user.id);
131→    return shares.map((s) => ({
132→      shareId: s.id,
133→      recipientPublicKey: s.recipient.publicKey,
134→      itemType: s.itemType,
135→      ipnsName: s.ipnsName,
136→      itemName: s.itemName,
137→      createdAt: s.createdAt,
138→    }));
139→  }
140→
141→  @Get('lookup')
142→  @ApiOperation({
143→    summary: 'Look up user by public key',
144→    description: 'Verify a public key belongs to a registered CipherBox user.',
145→  })
146→  @ApiQuery({
147→    name: 'publicKey',
148→    description: 'Uncompressed secp256k1 public key (0x04...)',
149→    required: true,
150→  })
151→  @ApiResponse({ status: 200, description: 'User found' })
152→  @ApiResponse({ status: 401, description: 'Unauthorized' })
153→  @ApiResponse({ status: 404, description: 'User not found' })
154→  async lookupUser(@Query('publicKey') publicKey: string): Promise<{ exists: boolean }> {
155→    if (!publicKey || !/^0x04[0-9a-fA-F]{128}$/.test(publicKey)) {
156→      throw new BadRequestException(
157→        'Invalid public key format. Expected uncompressed secp256k1 key: 0x04 + 128 hex chars'
158→      );
159→    }
160→
161→    const exists = await this.sharesService.lookupUserByPublicKey(publicKey);
162→    if (!exists) {
163→      throw new NotFoundException('User not found');
164→    }
165→    return { exists: true };
166→  }
167→
168→  @Get('pending-rotations')
169→  @ApiOperation({
170→    summary: 'Get pending rotations',
171→    description:
172→      'Get shares that have been revoked but not yet key-rotated. ' +
173→      'Used by the client to detect lazy rotation needs before folder modification.',
174→  })
175→  @ApiResponse({
176→    status: 200,
177→    description: 'List of revoked shares pending rotation',
178→    type: [PendingRotationResponseDto],
179→  })
180→  @ApiResponse({ status: 401, description: 'Unauthorized' })
181→  async getPendingRotations(@Request() req: RequestWithUser): Promise<
182→    Array<{
183→      shareId: string;
184→      recipientPublicKey: string;
185→      itemType: string;
186→      ipnsName: string;
187→      itemName: string;
188→      revokedAt: Date;
189→    }>
190→  > {
191→    const shares = await this.sharesService.getPendingRotations(req.user.id);
192→    return shares.map((s) => ({
193→      shareId: s.id,
194→      recipientPublicKey: s.recipient.publicKey,
195→      itemType: s.itemType,
196→      ipnsName: s.ipnsName,
197→      itemName: s.itemName,
198→      revokedAt: s.revokedAt!,
199→    }));
200→  }
201→
202→  @Get(':shareId/keys')
203→  @ApiOperation({
204→    summary: 'Get share keys',
205→    description: 'Get all re-wrapped child keys for a share. Accessible by sharer or recipient.',
206→  })
207→  @ApiResponse({ status: 200, description: 'List of share keys', type: [ShareKeyResponseDto] })
208→  @ApiResponse({ status: 401, description: 'Unauthorized' })
209→  @ApiResponse({ status: 403, description: 'Not authorized to access this share' })
210→  @ApiResponse({ status: 404, description: 'Share not found' })
211→  async getShareKeys(
212→    @Request() req: RequestWithUser,
213→    @Param('shareId', ParseUUIDPipe) shareId: string
214→  ): Promise<
215→    Array<{
216→      keyType: string;
217→      itemId: string;
218→      encryptedKey: string;
219→    }>
220→  > {
221→    const keys = await this.sharesService.getShareKeys(shareId, req.user.id);
222→    return keys.map((k) => ({
223→      keyType: k.keyType,
224→      itemId: k.itemId,
225→      encryptedKey: k.encryptedKey.toString('hex'),
226→    }));
227→  }
228→
229→  @Post(':shareId/keys')
230→  @ApiOperation({
231→    summary: 'Add share keys',
232→    description: 'Add re-wrapped child keys to an existing share. Only the sharer can add keys.',
233→  })
234→  @ApiResponse({ status: 201, description: 'Keys added' })
235→  @ApiResponse({ status: 401, description: 'Unauthorized' })
236→  @ApiResponse({ status: 403, description: 'Only the sharer can add keys' })
237→  @ApiResponse({ status: 404, description: 'Share not found' })
238→  async addShareKeys(
239→    @Request() req: RequestWithUser,
240→    @Param('shareId', ParseUUIDPipe) shareId: string,
241→    @Body() dto: AddShareKeysDto
242→  ): Promise<void> {
243→    await this.sharesService.addShareKeys(shareId, req.user.id, dto);
244→  }
245→
246→  @Delete(':shareId')
247→  @HttpCode(HttpStatus.NO_CONTENT)
248→  @ApiOperation({
249→    summary: 'Revoke a share',
250→    description:
251→      'Soft-delete a share by setting revokedAt. ' +
252→      'Only the sharer can revoke. Keys are kept for lazy rotation.',
253→  })
254→  @ApiResponse({ status: 204, description: 'Share revoked' })
255→  @ApiResponse({ status: 401, description: 'Unauthorized' })
256→  @ApiResponse({ status: 403, description: 'Only the sharer can revoke' })
257→  @ApiResponse({ status: 404, description: 'Share not found' })
258→  async revokeShare(
259→    @Request() req: RequestWithUser,
260→    @Param('shareId', ParseUUIDPipe) shareId: string
261→  ): Promise<void> {
262→    await this.sharesService.revokeShare(shareId, req.user.id);
263→  }
264→
265→  @Patch(':shareId/hide')
266→  @HttpCode(HttpStatus.NO_CONTENT)
267→  @ApiOperation({
268→    summary: 'Hide a share',
269→    description: 'Mark a share as hidden by the recipient. Only the recipient can hide.',
270→  })
271→  @ApiResponse({ status: 204, description: 'Share hidden' })
272→  @ApiResponse({ status: 401, description: 'Unauthorized' })
273→  @ApiResponse({ status: 403, description: 'Only the recipient can hide' })
274→  @ApiResponse({ status: 404, description: 'Share not found' })
275→  async hideShare(
276→    @Request() req: RequestWithUser,
277→    @Param('shareId', ParseUUIDPipe) shareId: string
278→  ): Promise<void> {
279→    await this.sharesService.hideShare(shareId, req.user.id);
280→  }
281→
282→  @Patch(':shareId/encrypted-key')
283→  @HttpCode(HttpStatus.NO_CONTENT)
284→  @ApiOperation({
285→    summary: 'Update share encrypted key',
286→    description:
287→      'Update the encrypted key on an existing share after lazy key rotation. ' +
288→      'Only the sharer can update the key.',
289→  })
290→  @ApiResponse({ status: 204, description: 'Encrypted key updated' })
291→  @ApiResponse({ status: 401, description: 'Unauthorized' })
292→  @ApiResponse({ status: 403, description: 'Only the sharer can update' })
293→  @ApiResponse({ status: 404, description: 'Share not found' })
294→  async updateShareEncryptedKey(
295→    @Request() req: RequestWithUser,
296→    @Param('shareId', ParseUUIDPipe) shareId: string,
297→    @Body() dto: UpdateEncryptedKeyDto
298→  ): Promise<void> {
299→    await this.sharesService.updateShareEncryptedKey(shareId, req.user.id, dto.encryptedKey);
300→  }
301→
302→  @Delete(':shareId/complete-rotation')
303→  @HttpCode(HttpStatus.NO_CONTENT)
304→  @ApiOperation({
305→    summary: 'Complete key rotation',
306→    description:
307→      'Hard-delete a revoked share after the sharer has rotated the folder key. ' +
308→      'Called after the client performs lazy key rotation.',
309→  })
310→  @ApiResponse({ status: 204, description: 'Share hard-deleted after rotation' })
311→  @ApiResponse({ status: 401, description: 'Unauthorized' })
312→  @ApiResponse({ status: 403, description: 'Only the sharer can complete rotation' })
313→  @ApiResponse({ status: 404, description: 'Share not found' })
314→  @ApiResponse({ status: 409, description: 'Share has not been revoked' })
315→  async completeRotation(
316→    @Request() req: RequestWithUser,
317→    @Param('shareId', ParseUUIDPipe) shareId: string
318→  ): Promise<void> {
319→    await this.sharesService.completeRotation(shareId, req.user.id);
320→  }
